unsigned int fn_16(unsigned char *data, unsigned long len, unsigned int seed)
{
    unsigned long i;
    unsigned int hash = seed;

    for (i = 0; i < len; i++)
    {
        hash ^= data[i];
        hash = (hash << 7) | (hash >> 25);
        hash += data[i] * 167;
    }

    hash ^= hash >> 15;
    hash *= 61;
    hash ^= hash >> 13;
    hash *= 97;
    hash ^= hash >> 16;

    return hash;
}
